            out.append((col, cells))
    return out

def _norm(cells):
    rs = [r for r, c in cells]; cs = [c for r, c in cells]
    return tuple(sorted((r-min(rs), c-min(cs)) for r, c in cells))

def _mindist(a, b):
    return min(abs(r1-r2)+abs(c1-c2) for r1, c1 in a for r2, c2 in b)

def _L(g, bg):
    Ls = []
    for c, cl in _shapes(g, bg):
        for r0, c0 in cl:
            if all(r == r0 or cc == c0 for r, cc in cl):
                vlen = sum(1 for r, cc in cl if cc == c0)
                hlen = sum(1 for r, cc in cl if r == r0)
                if vlen >= 3 and hlen >= 3:
                    Ls.append((c, cl)); break
    return max(Ls, key=lambda x: len(x[1])) if Ls else None

def transform(grid):
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
